using System;
using System.Linq;
using UnityEngine;
using UnityEngine.SceneManagement;

public sealed class GridShiftApartment:MonoBehaviour {
 public static GridShiftApartment Instance{get;private set;}public Vector3 spawn;public Vector3 look=Vector3.forward;
 void Awake(){Instance=this;}
 void OnDestroy(){if(Instance==this)Instance=null;}
 public void Configure(){if(GetComponent<GridShiftHomeEnvironment>()==null)gameObject.AddComponent<GridShiftHomeEnvironment>();
 var outlook=GetComponent<GridShiftApartmentView>();if(outlook!=null)Destroy(outlook);
 foreach(string obsolete in new[]{"Hallway","Terrace doorway frame","Terrace exterior doorframe","Apartment city outlook and terrace"}){var t=transform.Find(obsolete);if(t!=null){t.gameObject.SetActive(false);Destroy(t.gameObject);}}
 var front=transform.Find("Apartment_01/Doors Frames/DoorFrame_Apt_03");
 foreach(var r in GetComponentsInChildren<Renderer>(true))if(r.name=="Int_Apt_01_Wall_01 (19)"){r.enabled=true;foreach(var c in r.GetComponents<Collider>())c.enabled=true;}
 foreach(var exit in GetComponentsInChildren<GridShiftWorldAction>(true))if(exit.title=="Sair de casa"&&front!=null&&!exit.sceneAuthored){exit.transform.position=front.position+new Vector3(0,1.5f,1.24f);NormalizeFocus(exit.transform);exit.sightRoot=front;exit.focusOwner=front;exit.focusOffset=Vector3.zero;exit.focusSize=new Vector3(1.6f,2.8f,.35f);exit.range=3;if(exit.FocusCollider is BoxCollider box){box.center=exit.focusOffset;box.size=exit.focusSize;}}

  foreach(var exit in GetComponentsInChildren<GridShiftWorldAction>(true))if(exit.title=="Sair de casa")exit.action=p=>{WorldSession.Instance.RequestTransition("SampleScene",p.transform);return true;};
  foreach(var t in GetComponentsInChildren<Transform>(true))if(t.name.IndexOf("Ceiling",StringComparison.OrdinalIgnoreCase)>=0)foreach(var r in t.GetComponentsInChildren<Renderer>(true))r.gameObject.layer=12;
  foreach(var map in UnityEngine.Object.FindObjectsByType<MinimapCamera>(FindObjectsSortMode.None))if(map.gameObject.scene==gameObject.scene)map.GetComponent<Camera>().cullingMask&=~(1<<12);
  foreach(var t in GetComponentsInChildren<Transform>(true))if(t.name.StartsWith("TV_Apt_")&&t.GetComponent<GridShiftHomeTV>()==null)t.gameObject.AddComponent<GridShiftHomeTV>();
  foreach(var legacy in GetComponentsInChildren<MonoBehaviour>(true))if(legacy!=null&&legacy.GetType().Namespace=="SojaExiles")legacy.enabled=false;
  foreach(var animator in GetComponentsInChildren<Animator>(true)){if(IsLocked(animator.transform)){animator.enabled=false;continue;}if(front!=null&&animator.transform.IsChildOf(front)){animator.enabled=false;continue;}if(animator.runtimeAnimatorController==null)continue;var clips=animator.runtimeAnimatorController.animationClips;string opening=clips.FirstOrDefault(c=>c.name.IndexOf("open",StringComparison.OrdinalIgnoreCase)>=0)?.name;string closing=clips.FirstOrDefault(c=>c.name.IndexOf("clos",StringComparison.OrdinalIgnoreCase)>=0)?.name;if(opening==null||closing==null)continue;var item=animator.GetComponent<GridShiftHomeFurniture>();if(item==null)item=animator.gameObject.AddComponent<GridShiftHomeFurniture>();item.Configure(animator,opening,closing);}
 }
 public static bool IsLocked(Transform item){for(var t=item;t!=null;t=t.parent){if(t.name=="Furniture"||t.name=="Windows")return true;if(t.name.StartsWith("DoorFrame_Apt_02"))return true;if(t.GetComponent<GridShiftApartment>()!=null)break;}var door=item.GetComponent<MeshRenderer>();if(door!=null&&item.GetComponentInParent<GridShiftHomeUse>()==null&&item.parent!=null&&item.parent.name.StartsWith("DoorFrame_Apt_01")){var b=door.bounds;var normal=b.size.x<b.size.z?Vector3.right:Vector3.forward;foreach(float side in new[]{-1f,1f}){var at=b.center+normal*side*.85f;bool floor=Physics.RaycastAll(at,Vector3.down,2.5f,~((1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore).Any(h=>h.normal.y>.8f&&h.transform.IsChildOf(item.GetComponentInParent<GridShiftApartment>().transform));if(!floor)return true;}}return false;}
 public static void NormalizeFocus(Transform focus){if(focus.GetComponent<GridShiftWorldAction>()?.sceneAuthored==true)return;var s=focus.parent.lossyScale;focus.localScale=new Vector3(Mathf.Abs(s.x)>.001f?1/s.x:1,Mathf.Abs(s.y)>.001f?1/s.y:1,Mathf.Abs(s.z)>.001f?1/s.z:1);focus.rotation=Quaternion.identity;}
 public void AddUse(Transform furniture,string kind,string title,Vector3 local){if(kind=="shower"&&furniture.GetComponent<GridShiftHomeBath>()==null)furniture.gameObject.AddComponent<GridShiftHomeBath>();var action=GridShiftWorldAction.Create(furniture,title,local,p=>kind=="shower"?furniture.GetComponent<GridShiftHomeBath>().Use(p):GridShiftLife.Instance!=null&&GridShiftLife.Instance.Use(kind,p,furniture));if(action.sceneAuthored)return;NormalizeFocus(action.transform);action.sightRoot=furniture;action.focusOwner=furniture;action.focusOffset=Vector3.up*.5f;action.focusSize=new Vector3(.65f,1,.65f);action.range=2.7f;}
}
public sealed class GridShiftHomeFurniture:MonoBehaviour {
 Animator animator;string opening,closing,id;bool open;float busyUntil;
 public void Configure(Animator a,string o,string c){animator=a;opening=o;closing=c;id="";for(var t=transform;t!=null&&t.GetComponent<GridShiftApartment>()==null;t=t.parent)id=t.name+"["+t.GetSiblingIndex()+"]/"+id;open=GridShiftLife.Instance?.State.openFurniture.Contains(id)==true;if(open)animator.Play(opening,0,1);var renderer=GetComponentsInChildren<Renderer>().FirstOrDefault();var pos=renderer!=null?transform.InverseTransformPoint(renderer.bounds.center):Vector3.up;var action=GridShiftWorldAction.Create(transform,"Abrir / fechar "+(opening.ToLowerInvariant().Contains("pull")?"gaveta":name.ToLowerInvariant().Contains("window")?"janela":"porta do móvel"),pos,p=>Toggle());if(action.sceneAuthored)return;GridShiftApartment.NormalizeFocus(action.transform);var owner=transform;while(owner.parent!=null&&owner.parent.GetComponent<GridShiftApartment>()==null&&owner.parent.name!="Furniture"&&owner.parent.name!="Doors Frames"&&owner.parent.name!="Windows"&&owner.parent.name!="Props")owner=owner.parent;action.sightRoot=owner;action.focusOwner=transform;action.range=2.7f;action.focusOffset=Vector3.zero;action.focusRadius=.2f;}
 public bool Toggle(){if(Time.time<busyUntil||GridShiftLife.Instance?.Dead==true)return false;busyUntil=Time.time+.65f;open=!open;animator.Play(open?opening:closing,0,0);var life=GridShiftLife.Instance;if(life!=null){var list=life.State.openFurniture.ToList();if(open&&!list.Contains(id))list.Add(id);else if(!open)list.Remove(id);life.State.openFurniture=list.ToArray();life.Changed();}return true;}
}
